const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Dry Chaco region (approximate extent)
  const dryChaco = ee.Geometry.Polygon([
    [[-65.0, -27.5], [-65.0, -19.0], [-57.0, -19.0], [-57.0, -27.5], [-65.0, -27.5]]
  ]);

  // Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Get tree cover in year 2000 (percentage)
  const treeCover2000 = hansen.select('treecover2000');

  // Get loss year (1-23 for 2001-2023)
  const lossYear = hansen.select('lossyear');

  // Create forest mask (>30% tree cover)
  const forestMask2000 = treeCover2000.gte(30);

  // Calculate initial forest area in 2000
  const forest2000 = forestMask2000.multiply(ee.Image.pixelArea());

  const stats2000 = forest2000.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dryChaco,
    scale: 3000,
    maxPixels: 1e9
  });

  const area2000 = stats2000.getInfo();

  if (!area2000 || !area2000.treecover2000) {
    console.log("No data available for Dry Chaco");
    console.log("<answer>C1</answer>");
    return;
  }

  const forest2000Area = area2000.treecover2000;

  // Check for valid pixels
  if (forest2000Area === 0) {
    console.log("No valid forest pixels in 2000");
    console.log("<answer>C2</answer>");
    return;
  }

  // Create mask for forest loss between 2001-2019 (lossyear 1-19)
  const loss2000to2019 = lossYear.gte(1).and(lossYear.lte(19)).and(forestMask2000);

  // Calculate forest loss area
  const forestLoss = loss2000to2019.multiply(ee.Image.pixelArea());

  const statsLoss = forestLoss.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dryChaco,
    scale: 3000,
    maxPixels: 1e9
  });

  const lossData = statsLoss.getInfo();

  if (!lossData || lossData.lossyear === undefined) {
    console.log("Loss calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  const lossArea = lossData.lossyear;

  // Calculate percentage decrease
  const percentDecrease = (lossArea / forest2000Area) * 100;

  // Convert to km²
  const forest2000Km2 = forest2000Area / 1e6;
  const lossKm2 = lossArea / 1e6;

  // Validation
  if (percentDecrease < 0 || percentDecrease > 100 || isNaN(percentDecrease)) {
    console.log("Invalid percentage calculation");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Forest 2000: ${forest2000Km2.toFixed(0)} km²`);
  console.log(`Loss 2000-2019: ${lossKm2.toFixed(0)} km²`);
  console.log(`Decrease: ${percentDecrease.toFixed(2)}%`);

  if (percentDecrease > 10) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
